import React from "react";
import { Link } from "react-router-dom";

const Navbar = () => {
    return (
        <nav style={{ padding: "1rem", background: "#282c34", color: "white" }}>
            <ul
                style={{
                    listStyle: "none",
                    display: "flex",
                    justifyContent: "center", // Centers the links horizontally
                    alignItems: "center", // Ensures vertical alignment
                    gap: "2rem", // Adds spacing between the links
                    margin: "0",
                    padding: "0",
                }}
            >
                <li>
                    <Link
                        to="/"
                        style={{
                            color: "white",
                            textDecoration: "none", // Removes the underline
                            fontSize: "1.2rem",
                            fontWeight: "bold",
                            transition: "color 0.3s ease",
                        }}
                        onMouseOver={(e) => (e.target.style.color = "#61dafb")}
                        onMouseOut={(e) => (e.target.style.color = "white")}
                    >
                        Home
                    </Link>
                </li>
                <li>
                    <Link
                        to="/admin-dashboard"
                        style={{
                            color: "white",
                            textDecoration: "none",
                            fontSize: "1.2rem",
                            fontWeight: "bold",
                            transition: "color 0.3s ease",
                        }}
                        onMouseOver={(e) => (e.target.style.color = "#61dafb")}
                        onMouseOut={(e) => (e.target.style.color = "white")}
                    >
                        Admin
                    </Link>
                </li>
                <li>
                    <Link
                        to="/user-dashboard"
                        style={{
                            color: "white",
                            textDecoration: "none",
                            fontSize: "1.2rem",
                            fontWeight: "bold",
                            transition: "color 0.3s ease",
                        }}
                        onMouseOver={(e) => (e.target.style.color = "#61dafb")}
                        onMouseOut={(e) => (e.target.style.color = "white")}
                    >
                        User
                    </Link>
                </li>
                <li>
                    <Link
                        to="/login"
                        style={{
                            color: "white",
                            textDecoration: "none",
                            fontSize: "1.2rem",
                            fontWeight: "bold",
                            transition: "color 0.3s ease",
                        }}
                        onMouseOver={(e) => (e.target.style.color = "#61dafb")}
                        onMouseOut={(e) => (e.target.style.color = "white")}
                    >
                        Login
                    </Link>
                </li>
            </ul>
        </nav>
    );
};

export default Navbar;
